"""Create five Codex r2 notebooks; no scientific calculations run by this builder."""
from pathlib import Path
import nbformat as nbf
OUT=Path(__file__).resolve().parent
HEADINGS=['Data acquisition','Processing','Axis','Levels and eligibility','Model / released scores','Curves, controls and diagnostics','Historical result and decision']

def md(s):return nbf.v4.new_markdown_cell(s)
def code(s):return nbf.v4.new_code_cell(s.strip()+'\n')
def section(c,i,text,src):c.extend([md(f'## {i}. {HEADINGS[i-1]}\n\n{text}'),code(src)])
INTRO='''Run All invokes the source pipeline with `--force`: it recalculates the selected investigation from verified public inputs. Existing downloads can be reused after verification; derived result tables are not a substitute for the default calculation. The completed execution runs on exxact05. Use the documented Python environment and allow the source downloads, CPU time and disk space on a cold run.

The notebooks distinguish measured outcomes from investigations that originally stopped before scoring. For those stops, the reproduced objects are input levels, eligibility, resource diagnostics and the recorded decision; no performance curve is invented. Original results are comparison targets and historical evidence only. Reconstructed choices and numerical differences remain explicit.

See the [original report](../originals/REPORT.md), [candidate ledger](../originals/supporting/audit/candidate_axis_ledger.csv), [public sources](../methods/sources.json) and [pipeline](../methods/run_pipeline.py).'''
BOOT='''from pathlib import Path
import importlib.util,json,sys
import numpy as np
import pandas as pd
from IPython.display import display,JSON,Markdown
ROOT=next(p for p in [Path.cwd(),*Path.cwd().parents] if (p/'methods/replogle.py').is_file() and (p/'originals/REPORT.md').is_file())
spec=importlib.util.spec_from_file_location('state_codex_r2_notebook',ROOT/'notebooks/shared.py')
wf=importlib.util.module_from_spec(spec);spec.loader.exec_module(wf)
pd.set_option('display.max_colwidth',100);pd.set_option('display.max_rows',100)
manifest=wf.read_json(ROOT,'methods/sources.json')
sources=pd.DataFrame(manifest['inputs'])
display(sources[['path','bytes','sha256','url']])
if manifest.get('remote_observations'):
    display(Markdown('**Pinned observation-only source objects used for Replogle cell counts**'))
    display(pd.DataFrame(manifest['remote_observations']))
wf.source_functions(ROOT,'methods/acquire.py',['main'])
print('Manifest public input records:',len(sources))
print('The next cell executes actual source calculation for this investigation.')
'''
FIT='''wf.source_functions(ROOT,'methods/common.py',['fisher','cluster_fit','curve'])
'''
def start(title):return [md('# '+title+'\n\n'+INTRO)]
def save(name,c,stage,ids):
 n=nbf.v4.new_notebook(cells=c)
 n.metadata={'kernelspec':{'name':'python3','display_name':'Python 3','language':'python'},'language_info':{'name':'python'},'state_reconstruction':{'investigation':'state-codex-r2','stage':stage,'original_candidate_ids':ids,'chain':HEADINGS,'default_execution':'force_source_calculation','historical_outcomes':'comparison_targets_only','scientific_execution_host':'exxact05'}}
 nbf.validate(n);nbf.write(n,OUT/name)
 (OUT/name.replace('.ipynb','.py')).write_text('\n\n'.join(f'# Cell {i}\n'+x.source for i,x in enumerate(c) if x.cell_type=='code')+'\n')
 print(name,len(c),'cells')

